BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS accounts(id text PRIMARY KEY,email citext UNIQUE NOT NULL,display_name text NOT NULL,password_hash text NOT NULL,account_type text NOT NULL CHECK(account_type IN('BUYER','SELLER','STAFF')),status text NOT NULL DEFAULT 'ACTIVE',seller_id text,twofa_status text NOT NULL DEFAULT 'DISABLED',twofa_secret_enc text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS account_roles(account_id text NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN('BUYER','SELLER','DEALER','EXPERT','CATALOGUER','TRUST_REVIEWER','ADMIN')),granted_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(account_id,role));
CREATE TABLE IF NOT EXISTS sessions(id text PRIMARY KEY,account_id text NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,last_seen_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz,ip_hash text,user_agent text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_account_idx ON sessions(account_id); CREATE INDEX IF NOT EXISTS sessions_expiry_idx ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS twofa_backup_codes(account_id text NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,code_hash text NOT NULL,used_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(account_id,code_hash));
CREATE TABLE IF NOT EXISTS verification_cases(id text PRIMARY KEY,account_id text NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,subject_type text NOT NULL CHECK(subject_type IN('PERSON','ORGANIZATION')),case_type text NOT NULL CHECK(case_type IN('KYC','KYB')),status text NOT NULL CHECK(status IN('NOT_STARTED','PENDING','VERIFIED','REJECTED','EXPIRED')),provider text,provider_reference text,risk_level text,decision_reason text,submitted_at timestamptz,decided_at timestamptz,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS verification_account_idx ON verification_cases(account_id,case_type);
CREATE TABLE IF NOT EXISTS objects(id text PRIMARY KEY,object_code text UNIQUE NOT NULL,seller_id text,passport jsonb NOT NULL,catalogue_status text NOT NULL,trust_status text NOT NULL,publication_status text NOT NULL DEFAULT 'PRIVATE',passport_hash text,updated_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS provenance_entries(id text PRIMARY KEY,object_id text NOT NULL REFERENCES objects(id) ON DELETE CASCADE,sequence_no integer NOT NULL,event jsonb NOT NULL,evidence_status text NOT NULL,evidence_ref text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(object_id,sequence_no));
CREATE TABLE IF NOT EXISTS media_assets(id text PRIMARY KEY,entity_type text NOT NULL CHECK(entity_type IN('OBJECT','DRAFT')),entity_id text NOT NULL,storage_key text UNIQUE NOT NULL,content_type text NOT NULL,bytes bigint,sha256 text,etag text,role text NOT NULL,visibility text NOT NULL DEFAULT 'PRIVATE',status text NOT NULL DEFAULT 'UPLOADING',uploaded_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS media_entity_idx ON media_assets(entity_type,entity_id,created_at);
CREATE TABLE IF NOT EXISTS listings(id text PRIMARY KEY,object_id text NOT NULL,seller_id text NOT NULL,status text NOT NULL,payload jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_active_listing_per_object ON listings(object_id) WHERE status IN('ACTIVE','RESERVED');
CREATE TABLE IF NOT EXISTS auctions(id text PRIMARY KEY,object_id text NOT NULL,sale_id text NOT NULL,status text NOT NULL,current_bid bigint NOT NULL,ends_at timestamptz NOT NULL,state jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auction_bids(id text PRIMARY KEY,auction_id text NOT NULL REFERENCES auctions(id) ON DELETE CASCADE,account_id text NOT NULL REFERENCES accounts(id),max_amount bigint NOT NULL,visible_amount bigint NOT NULL,idempotency_key text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(account_id,idempotency_key));
CREATE TABLE IF NOT EXISTS offers(id text PRIMARY KEY,listing_id text NOT NULL,buyer_account_id text NOT NULL REFERENCES accounts(id),seller_id text NOT NULL,status text NOT NULL,payload jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders(id text PRIMARY KEY,listing_id text,object_id text NOT NULL,buyer_account_id text NOT NULL REFERENCES accounts(id),seller_id text NOT NULL,status text NOT NULL,payload jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS orders_buyer_idx ON orders(buyer_account_id,created_at DESC); CREATE INDEX IF NOT EXISTS orders_seller_idx ON orders(seller_id,created_at DESC);
CREATE TABLE IF NOT EXISTS notifications(id text PRIMARY KEY,account_id text NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,type text NOT NULL,payload jsonb NOT NULL DEFAULT '{}'::jsonb,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS notifications_account_idx ON notifications(account_id,created_at DESC);
CREATE TABLE IF NOT EXISTS seller_drafts(id text PRIMARY KEY,seller_id text NOT NULL,status text NOT NULL,payload jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS catalogue_reviews(id text PRIMARY KEY,draft_id text,object_id text,assigned_to text REFERENCES accounts(id),catalogue_status text NOT NULL,trust_status text NOT NULL,risk_flags jsonb NOT NULL DEFAULT '[]'::jsonb,requested_changes jsonb NOT NULL DEFAULT '[]'::jsonb,decision_note text,updated_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log(id bigserial PRIMARY KEY,actor_account_id text REFERENCES accounts(id),action text NOT NULL,entity_type text NOT NULL,entity_id text,request_id text,ip_hash text,before_data jsonb,after_data jsonb,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_entity_idx ON audit_log(entity_type,entity_id,created_at DESC); CREATE INDEX IF NOT EXISTS audit_actor_idx ON audit_log(actor_account_id,created_at DESC);
INSERT INTO schema_migrations(version) VALUES('001_v09_foundation') ON CONFLICT DO NOTHING;
COMMIT;
